CREATE TABLE ss_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password TEXT NOT NULL);
CREATE TABLE ss_sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES ss_users,expires BIGINT NOT NULL);
CREATE INDEX ss_sessions_user ON ss_sessions(user_id);
CREATE TABLE ss_documents(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES ss_users,title TEXT NOT NULL,state JSONB NOT NULL,revision BIGINT NOT NULL DEFAULT 0,updated BIGINT NOT NULL,structure_revision BIGINT NOT NULL DEFAULT 0,change_type TEXT NOT NULL DEFAULT 'create');
CREATE INDEX ss_documents_owner ON ss_documents(owner);
CREATE TABLE ss_permissions(document_id TEXT NOT NULL REFERENCES ss_documents ON DELETE CASCADE,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('viewer','commenter','editor')),PRIMARY KEY(document_id,email));
CREATE INDEX ss_permissions_email ON ss_permissions(email);
CREATE TABLE ss_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id TEXT NOT NULL REFERENCES ss_documents ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES ss_users,revision BIGINT NOT NULL,changes JSONB NOT NULL,created BIGINT NOT NULL);
CREATE INDEX ss_history_document ON ss_history(document_id,id DESC);
CREATE TABLE ss_versions(document_id TEXT NOT NULL REFERENCES ss_documents ON DELETE CASCADE,revision BIGINT NOT NULL,user_id TEXT NOT NULL REFERENCES ss_users,title TEXT NOT NULL,state JSONB NOT NULL,created BIGINT NOT NULL,PRIMARY KEY(document_id,revision));
CREATE TABLE ss_mutations(document_id TEXT NOT NULL REFERENCES ss_documents ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES ss_users,request_id TEXT NOT NULL,revision BIGINT NOT NULL,PRIMARY KEY(document_id,user_id,request_id));
CREATE TABLE ss_presence(document_id TEXT NOT NULL REFERENCES ss_documents ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES ss_users,session_token TEXT NOT NULL REFERENCES ss_sessions ON DELETE CASCADE,client_id TEXT NOT NULL,color TEXT NOT NULL,cursor JSONB,last_seen BIGINT NOT NULL,PRIMARY KEY(document_id,session_token,client_id));
CREATE INDEX ss_presence_document ON ss_presence(document_id,last_seen);
